import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { tap } from 'rxjs/operators';

const BASE = 'http://localhost:8000';

@Injectable({ providedIn: 'root' })
export class DashboardService {

  private cache: Record<string, { data: any; ts: number }> = {};
  private TTL = 60_000; // 1 min cache

  constructor(private http: HttpClient) {}

  private cached<T>(key: string, req: Observable<T>): Observable<T> {
    const hit = this.cache[key];
    if (hit && Date.now() - hit.ts < this.TTL) return of(hit.data as T);
    return req.pipe(tap(d => (this.cache[key] = { data: d, ts: Date.now() })));
  }

  invalidate() { this.cache = {}; }

  getSummary(userId: string): Observable<any> {
    return this.cached('summary', this.http.get(`${BASE}/dashboard/summary?user_id=${userId}`));
  }

  getTaskTrend(userId: string): Observable<any[]> {
    return this.cached('trend', this.http.get<any[]>(`${BASE}/dashboard/task-trend?user_id=${userId}`));
  }

  getCategoryDistribution(userId: string): Observable<any[]> {
    return this.cached('cat', this.http.get<any[]>(`${BASE}/dashboard/category-distribution?user_id=${userId}`));
  }

  getHeatmap(userId: string): Observable<any[]> {
    return this.cached('heatmap', this.http.get<any[]>(`${BASE}/dashboard/heatmap?user_id=${userId}`));
  }

  getInsights(userId: string): Observable<any> {
    return this.cached('insights', this.http.get(`${BASE}/dashboard/insights?user_id=${userId}`));
  }
}
